#[test]
fn tpsa_aspirin() {
    // RDKit: 63.60 Å²
    assert_approx(
        "TPSA aspirin",
        tpsa(&mol("CC(=O)Oc1ccccc1C(=O)O")),
        63.60,
        1.0,
    );
}

#[test]
fn tpsa_caffeine() {
    // RDKit: 61.82 Å²
    // Fix: aromatic N with deg≥3 (N-substituted) gets 4.93 (RDKit value), not 12.89.
    // 3 N-methyl/N-aryl @ 4.93 + 1 pyridine-type @ 12.89 + 2 C=O @ 17.07 = 61.82.
    assert_approx(
        "TPSA caffeine",
        tpsa(&mol("Cn1cnc2c1c(=O)n(c(=O)n2C)C")),
        61.82,
        1.0,
    );
}

