#[test]
fn tpsa_methotrexate() {
    // RDKit: 210.54 Å²
    assert_approx(
        "TPSA methotrexate",
        tpsa(&mol(
            "CN(Cc1cnc2nc(N)nc(N)c2n1)c1ccc(cc1)C(=O)NC(CCC(=O)O)C(=O)O",
        )),
        210.54,
        2.0,
    );
}

#[test]
fn tpsa_aspirin_no_ester_overcounting() {
    // Ensure ester O (ether-like) gets 9.23, not 17.07 or 20.23.
    // aspirin: CC(=O)Oc1ccccc1C(=O)O
    //   2 × C=O: 17.07 × 2 = 34.14
    //   1 × ester O (ether): 9.23
    //   1 × carboxyl OH: 20.23
    //   Total expected: 63.60
    let t = tpsa(&mol("CC(=O)Oc1ccccc1C(=O)O"));
    assert_approx("TPSA aspirin (ester O)", t, 63.60, 0.1);
}

